        return grid

    from collections import Counter

    rows = len(grid)
    cols = len(grid[0])

    # Count each value
    counts = Counter()
    for r in range(rows):
        for c in range(cols):
            counts[grid[r][c]] += 1

    # Background = most frequent
    background = max(counts.keys(), key=lambda x: counts[x])

    # Group positions by value
    positions = {}
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val != background:
                if val not in positions:
                    positions[val] = []
                positions[val].append((r, c))

    # Result grid initialized with background
    result = [[background for _ in range(cols)] for _ in range(rows)]

    # Create regions for each non-background value
    for val, pos_list in positions.items():
        min_r = min(p[0] for p in pos_list)
        max_r = max(p[0] for p in pos_list)
        min_c = min(p[1] for p in pos_list)
        max_c = max(p[1] for p in pos_list)

        # Fill the bounding box
        for r in range(min_r, max_r + 1):
            for c in range(min_c, max_c + 1):
                result[r][c] = val

    return result
